const nodes = [{"id":"start","name":"中央苏区","date":"1934.10","title":"战略转移，从中央苏区出发","text":"1934 年 10 月，中共中央和中央红军主力撤离中央革命根据地，开始长征。","source":"《多视角下看长征》·共产党员网","url":"https://www.12371.cn/2021/10/19/ARTI1634643519286309.shtml","x":83,"y":78,"questions":["中央红军什么时候开始长征？","各路红军都从这里出发吗？"],"extra":[{"id":"start_scope","text":"中央红军主力于 1934 年 10 月开始战略转移。红二十五军、红四方面军和红二、红六军团后来分别从不同根据地出发，时间和路线并不相同。","source":"《多视角下看长征》·共产党员网","url":"https://www.12371.cn/2021/10/19/ARTI1634643519286309.shtml"}]},{"id":"xiangjiang","name":"湘江","date":"1934.11—12","title":"突破封锁，付出重大代价","text":"1934 年 11 月 27 日至 12 月 1 日，中央红军进行湘江之战，突破敌军封锁，部队付出重大代价。","source":"《遵义会议：中国共产党历史的伟大转折》·共产党员网","url":"https://www.12371.cn/2021/08/12/ARTI1628761880703772.shtml","x":72,"y":70,"questions":["湘江之战发生在什么时候？","湘江之战付出了什么代价？"],"extra":[{"id":"xiangjiang_detail","text":"中央红军长征初期原计划向湘西北转移，与红二、红六军团会合；湘江之战中，红军突破敌军第四道封锁线，损失惨重。","source":"《遵义会议和红军长征的胜利》·共产党员网","url":"https://fuwu.12371.cn/2016/07/22/ARTI1469154834425831.shtml"}]},{"id":"zunyi","name":"遵义","date":"1935.01","title":"遵义会议，重要转折","text":"1935 年 1 月 15 日至 17 日，中共中央在贵州遵义召开政治局扩大会议，集中解决当时具有决定意义的军事和组织问题，是中国共产党历史上生死攸关的转折点。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100","x":55,"y":67,"questions":["遵义会议什么时候召开？","遵义会议为什么重要？"],"extra":[{"id":"zunyi_detail","text":"遵义会议批评第五次反“围剿”和长征以来军事领导上的错误，改组中央领导机构，选举毛泽东为中央政治局常委。会议是中国共产党独立自主解决路线、方针和政策的重要会议，在危急时刻挽救了党和红军。","source":"《党史百年·天天读：1月15日》·共产党员网","url":"https://www.12371.cn/2021/01/13/ARTI1610503077031871.shtml"}]},{"id":"chishui","name":"赤水河","date":"1935.01—03","title":"四渡赤水","text":"1935 年 1 月下旬至 3 月，中央红军在川黔滇边境地区四渡赤水河，机动周旋。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100","x":43,"y":58,"questions":["四渡赤水发生在什么时期？","第一次和第四次渡河分别是什么时候？"],"extra":[{"id":"chishui_detail","text":"1935 年 1 月 29 日，红军首次渡过赤水河；2 月 18 日至 21 日二渡；3 月 16 日至 17 日三渡；3 月 21 日至 22 日四渡。","source":"《党史百年·天天读：1月19日》·共产党员网","url":"https://www.12371.cn/2021/01/17/ARTI1610856841161387.shtml"}]},{"id":"jinsha","name":"金沙江","date":"1935.05","title":"巧渡金沙江","text":"1935 年 5 月上旬，中央红军渡过金沙江，摆脱敌军的围追堵截，继续北上。","source":"《红军长征巧渡金沙江，“巧”在哪里？》·共产党员网","url":"https://www.12371.cn/2023/08/20/ARTI1692495372136387.shtml","x":29,"y":72,"questions":["中央红军什么时候渡过金沙江？","巧渡金沙江有哪些策略？"],"extra":[{"id":"jinsha_detail","text":"1935 年 4 月，中央红军佯攻昆明，调动敌军，创造北渡金沙江的条件。先遣部队于 5 月 3 日抵达皎平渡，为主力渡江打前站。","source":"《七只船 三万人》·共产党员网","url":"https://news.12371.cn/2016/10/13/ARTI1476351910026867.shtml"}]},{"id":"luding","name":"泸定桥","date":"1935.05","title":"飞夺泸定桥","text":"1935 年 5 月 29 日，中央红军部队夺取大渡河上的泸定桥，为继续北上打开通路。","source":"《将精神的种子埋入时间》·共产党员网","url":"https://news.12371.cn/2016/10/19/ARTI1476825092629521.shtml","x":22,"y":48,"questions":["飞夺泸定桥发生在什么时候？","夺取泸定桥有什么作用？"],"extra":[{"id":"luding_detail","text":"1935 年 5 月 29 日，中央红军左纵队先头部队从泸定桥西头发起夺桥战斗，抢占大桥。","source":"《党史百年·天天读：5月29日》·共产党员网","url":"https://www.12371.cn/2021/05/27/ARTI1622097439084125.shtml"}]},{"id":"wuqi","name":"吴起镇","date":"1935.10","title":"抵达陕北","text":"1935 年 10 月 19 日，中共中央率红军陕甘支队到达陕北吴起镇，中央红军主力长征胜利结束。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100","x":69,"y":23,"questions":["陕甘支队什么时候到达吴起镇？","到达吴起镇有什么意义？"]},{"id":"huining","name":"会宁","date":"1936.10.09","title":"红一、红四方面军会师","text":"1936 年 10 月 9 日，红四方面军在甘肃会宁与红一方面军会师。","source":"《多视角下看长征》·共产党员网","url":"https://www.12371.cn/2021/10/19/ARTI1634643519286309.shtml","x":43,"y":26,"questions":["哪些部队在会宁会师？","会宁会师发生在什么时候？"]},{"id":"jiangtaibao","name":"将台堡","date":"1936.10.22","title":"红一、红二方面军会师","text":"1936 年 10 月 22 日，红二方面军在将台堡（今属宁夏西吉）与红一方面军会师。三大主力先后会师，标志着红军长征胜利结束。","source":"《多视角下看长征》·共产党员网","url":"https://www.12371.cn/2021/10/19/ARTI1634643519286309.shtml","x":54,"y":13,"questions":["哪些部队在将台堡会师？","将台堡会师有什么意义？"]}];
const json = (value, status = 200) => Response.json(value, {status, headers:{'cache-control':'no-store','x-content-type-options':'nosniff'}});
const MAX_BODY = 12000;
const SESSION_RE=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i;
const encode64 = bytes => btoa(Array.from(bytes, b=>String.fromCharCode(b)).join('')).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
function decode64(value){if(!/^[A-Za-z0-9_-]+$/.test(value))throw new Error('invalid token');const binary=atob(value.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-value.length%4)%4));return Uint8Array.from(binary,c=>c.charCodeAt(0));}
async function signingKey(secret){return crypto.subtle.importKey('raw',new TextEncoder().encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign','verify']);}
async function issueToken(key,entry){const payload=encode64(new TextEncoder().encode(JSON.stringify(entry)));const signature=await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(payload));return payload+'.'+encode64(new Uint8Array(signature));}
async function readToken(key,token,sessionId,node){try{if(typeof token!=='string'||token.length>7000)return null;const parts=token.split('.');if(parts.length!==2)return null;const valid=await crypto.subtle.verify('HMAC',key,decode64(parts[1]),new TextEncoder().encode(parts[0]));if(!valid)return null;const entry=JSON.parse(new TextDecoder().decode(decode64(parts[0])));if(entry.v!==1||entry.sessionId!==sessionId||entry.node!==node||!Number.isSafeInteger(entry.at)||entry.at>Date.now()+60000||Date.now()-entry.at>3600000||typeof entry.question!=='string'||entry.question.length>500||typeof entry.answer!=='string'||entry.answer.length>800||!Array.isArray(entry.sources)||entry.sources.some(id=>typeof id!=='string'||!nodes.some(n=>n.id===id||(n.extra||[]).some(e=>e.id===id))))return null;return entry;}catch{return null;}}

